/* ============================================================
   조업 일정표 (뒤집힌 보트 집#3)
   ============================================================ */
.story-content .schedule-sheet {
    position: relative;
    margin: 1.4rem 0 1.2rem;
    padding: 1.5rem 1rem 1rem;
    background:
        repeating-linear-gradient(180deg, transparent 0, transparent 27px, rgba(70, 90, 120, 0.1) 27px, rgba(70, 90, 120, 0.1) 28px),
        linear-gradient(180deg, #e9e5d8 0%, #dcd6c3 100%);
    color: #23262b;
    font-family: "Noto Sans KR", sans-serif;
    border: 1px solid rgba(110, 105, 85, 0.6);
    box-shadow: inset 0 0 18px rgba(90, 80, 50, 0.22), 0 4px 12px rgba(0, 0, 0, 0.45);
    transform: rotate(-0.6deg);
}

/* 압정 */
.story-content .schedule-sheet::before {
    content: "";
    position: absolute;
    top: -7px;
    left: 50%;
    width: 14px;
    height: 14px;
    margin-left: -7px;
    border-radius: 50%;
    background: radial-gradient(circle at 35% 30%, #f08a7a 0%, #b53a2e 55%, #7a1f18 100%);
    box-shadow: 1px 3px 4px rgba(0, 0, 0, 0.5);
}

.story-content .schedule-sheet .schedule-title {
    margin-bottom: 0.7rem;
    padding-bottom: 0.4rem;
    border-bottom: 2px solid rgba(35, 38, 43, 0.75);
    text-align: center;
    font-size: 1.1rem;
    font-weight: 900;
    letter-spacing: 0.14em;
    color: #1b1d21;
}

.story-content .schedule-sheet table.schedule-table {
    width: 100%;
    border-collapse: collapse;
    table-layout: fixed;
    font-size: 0.92rem;
    background: rgba(255, 255, 255, 0.22);
}

.story-content .schedule-sheet .schedule-table th,
.story-content .schedule-sheet .schedule-table td {
    padding: 0.5rem 0.55rem;
    border: 1px solid rgba(35, 38, 43, 0.55);
    text-align: center;
    vertical-align: middle;
    color: #23262b;
    background: none;
}

.story-content .schedule-sheet .schedule-table th {
    background: rgba(60, 80, 110, 0.18);
    font-weight: 800;
    letter-spacing: 0.1em;
    font-size: 0.82rem;
}

.story-content .schedule-sheet .schedule-table th:nth-child(1) { width: 25%; }
.story-content .schedule-sheet .schedule-table th:nth-child(2) { width: 45%; }
.story-content .schedule-sheet .schedule-table th:nth-child(3) { width: 30%; }

.story-content .schedule-sheet .schedule-table td.sch-kind {
    font-weight: 800;
    background: rgba(60, 80, 110, 0.1);
}

.story-content .schedule-sheet .schedule-table td.sch-date {
    font-size: 0.82rem;
    color: #2b3a55;
}

.story-content .schedule-sheet .emphasis {
    color: #1b1d21;
    font-weight: 800;
    text-decoration: none;
    background: linear-gradient(transparent 55%, rgba(205, 120, 40, 0.42) 55%);
    padding: 0 0.1em;
    white-space: nowrap;
}
